import pytest

from billing import fetch_invoices, format_cpf


def test_fetch_newest_first():
    store = [{"date": "2026-01-01"}, {"date": "2026-02-01"}]
    assert fetch_invoices(store)[0]["date"] == "2026-02-01"


def test_format_cpf_returns_masked_layout():
    assert format_cpf("12345678909") == "123.456.789-09"


def test_format_cpf_accepts_formatted_input():
    assert format_cpf("123.456.789-09") == "123.456.789-09"


def test_format_cpf_rejects_wrong_length():
    with pytest.raises(ValueError):
        format_cpf("1234")

